from flask import Flask, request, jsonify, abort
from flask_cors import CORS
from flask_limiter import Limiter
from marshmallow import Schema, fields, ValidationError

app = Flask(__name__)
CORS(app)
limiter = Limiter(app, key_func=lambda: request.remote_addr)

class ProfileSchema(Schema):
    username = fields.Str(required=True)
    email = fields.Email(required=True)

@app.route("/profile", methods=["POST"])
@limiter.limit("5 per minute")  # Limit requests to avoid DoS
def profile():
    if not request.is_json:
        abort(400, description="Invalid input format. JSON required.")

    try:
        raw_data = request.get_json()
        # Validate and sanitize raw_data
        validated_data = ProfileSchema().load(raw_data)

        # Process the validated data as needed
        return jsonify(validated_data), 200
    except ValidationError as err:
        abort(400, description=str(err.messages))
    except Exception as e:
        # Log the error internally (configure logging as needed)
        app.logger.error(f"Internal Server Error: {e}")
        abort(500, description="Internal Server Error")

if __name__ == "__main__":
    app.run(debug=False)  # Ensure debug mode is off in production

