from flask import Flask, request, jsonify
import os
import logging
import re
from werkzeug.utils import secure_filename
from functools import wraps
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address

app = Flask(__name__)

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s:%(message)s')

# Load the allowed directory from environment variable
ALLOWED_DIRECTORY = os.getenv('ALLOWED_DIRECTORY', '/safe/directory')
MAX_FILENAME_LENGTH = 255  # Limit filename length
MAX_FILE_SIZE = 5 * 1024 * 1024  # Limit file size to 5 MB

# Initialize rate limiting
limiter = Limiter(get_remote_address, default_limits=["100 per minute"])

def is_safe_file(filename):
    if not re.match(r'^[A-Za-z0-9_.-]+$', filename):
        return False
    normalized_path = os.path.normpath(os.path.join(ALLOWED_DIRECTORY, secure_filename(filename)))
    return normalized_path.startswith(os.path.abspath(ALLOWED_DIRECTORY)) and os.path.isfile(normalized_path)

def require_https(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if not request.is_secure:
            return jsonify({"error": "HTTPS required"}), 403
        return f(*args, **kwargs)
    return decorated_function

@app.route("/filedata")
@limiter.limit("10 per second")
@require_https
def get_file_data():
    filename = request.args.get('filename')

    if filename and isinstance(filename, str) and len(filename) <= MAX_FILENAME_LENGTH:
        if is_safe_file(filename):
            try:
                file_path = os.path.join(ALLOWED_DIRECTORY, secure_filename(filename))
                if os.path.getsize(file_path) > MAX_FILE_SIZE:
                    return jsonify({"error": "File size exceeds limit."}), 413
                with open(file_path, 'r') as file:
                    data = file.read()
                app.logger.info(f"File accessed: {filename} by {request.remote_addr}")
                response = jsonify({"data": data})
                response.headers["Content-Type"] = "application/json"
                return response
            except Exception:
                app.logger.error("Error reading file.", exc_info=False)
                return jsonify({"error": "Internal server error."}), 500
        else:
            return jsonify({"error": "Invalid filename or file does not exist."}), 400
    else:
        return jsonify({"error": "Invalid filename format."}), 400

if __name__ == "__main__":
    app.run(ssl_context=('path/to/cert.pem', 'path/to/key.pem'))

