    if not is_valid_process_id(processID):
        logging.warning("Invalid process ID.")
        return errno.EINVAL

    if not check_permissions(processID):
        logging.warning("Permission denied: Cannot kill process.")
        return errno.EACCES

    try:
        if not signal.valid(signal_type):
            logging.error("Invalid signal type provided.")
            return errno.EINVAL

