import tempfile
import os
import stat

def write_results(results):
    if not isinstance(results, str):
        raise ValueError("Results must be a string.")

    try:
        with tempfile.NamedTemporaryFile(delete=False, mode='w', encoding='utf-8') as temp_file:
            temp_file.write(results)
            temp_file_name = temp_file.name

        # Set permissions to restrict access
        os.chmod(temp_file_name, stat.S_IRUSR | stat.S_IWUSR)  # Readable and writable by owner only

    except OSError as e:
        raise RuntimeError("Unable to create temporary file.") from e

    return temp_file_name

file_name = None
try:
    file_name = write_results("Example results data.")
    print(f"Temporary file created: {file_name}")
except ValueError as ve:
    print(f"ValueError: {ve}")
except RuntimeError as re:
    print(f"RuntimeError: {re}")
except Exception as e:
    print(f"An unexpected error occurred: {e}")
finally:
    if file_name and os.path.exists(file_name):
        try:
            os.remove(file_name)
        except OSError as e:
            print(f"Error removing temporary file: {e}")

