import hmac
import hashlib
import time
from datetime import datetime, timedelta

# Configuration for rate limiting
RATE_LIMIT_WINDOW = timedelta(minutes=1)
MAX_ATTEMPTS = 5
failed_attempts = {}
lockout_time = {}

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()  # Use a secure hashing function like bcrypt or Argon2 in production

def is_rate_limited(user_id):
    now = datetime.now()
    if user_id in lockout_time:
        if now < lockout_time[user_id]:
            return True
        else:
            del lockout_time[user_id]

    attempts = failed_attempts.get(user_id, [])
    failed_attempts[user_id] = [attempt for attempt in attempts if now - attempt < RATE_LIMIT_WINDOW]

    return len(failed_attempts[user_id]) >= MAX_ATTEMPTS

def log_failed_attempt(user_id):
    now = datetime.now()
    if user_id not in failed_attempts:
        failed_attempts[user_id] = []
    failed_attempts[user_id].append(now)

def validate_password(user_id, hashed_pw, typed_pw):
    if is_rate_limited(user_id):
        return False  # User is temporarily blocked due to too many failed attempts

    is_valid = hmac.compare_digest(hashed_pw, hash_password(typed_pw))

    if not is_valid:
        log_failed_attempt(user_id)

    return is_valid

