import logging
from time import time

MAX_LOAD_SIZE = 512
RATE_LIMIT_WINDOW = 60  # seconds
RATE_LIMIT_MAX_REQUESTS = 100

request_times = {}

def log_request(addr):
    current_time = time()
    if addr not in request_times:
        request_times[addr] = []
    request_times[addr] = [t for t in request_times[addr] if t > current_time - RATE_LIMIT_WINDOW]
    request_times[addr].append(current_time)

def is_rate_limited(addr):
    return len(request_times.get(addr, [])) > RATE_LIMIT_MAX_REQUESTS

def parseUDPpacket(data):
    if len(data) < 12:
        raise ValueError("Incoming data too short")

    transaction_id = struct.unpack('>H', data[:2])[0]
    flags = struct.unpack('>H', data[2:4])[0]
    questions = struct.unpack('>H', data[4:6])[0]
    answer_rrs = struct.unpack('>H', data[6:8])[0]
    authority_rrs = struct.unpack('>H', data[8:10])[0]
    additional_rrs = struct.unpack('>H', data[10:12])[0]

    offset = 12
    questions_list = []

    for _ in range(questions):
        name, offset = parse_name(data, offset)
        if offset + 4 > len(data):
            raise ValueError("Incomplete question section")
        qtype = struct.unpack('>H', data[offset:offset + 2])[0]
        qclass = struct.unpack('>H', data[offset + 2:offset + 4])[0]
        questions_list.append((name, qtype, qclass))
        offset += 4

    return transaction_id, questions_list

