import logging
import os
from datetime import datetime, timedelta
import jwt  # Ensure you have PyJWT installed

SECRET_KEY = os.getenv('JWT_SECRET_KEY')

def confirmAuth(headers):
    auth_token = headers.get('Authorization')
    if not auth_token:
        logging.warning("No authorization token provided.")
        return None

    try:
        token_object = jwt.decode(auth_token, SECRET_KEY, algorithms=['HS256'], options={"require": ["exp", "iat", "aud", "iss"]})

        if not validateClaims(token_object):
            logging.warning("Invalid claims in token.")
            return None

        return token_object['data']

    except jwt.ExpiredSignatureError:
        logging.warning("Token expired. Consider requesting a new token.")
    except jwt.InvalidTokenError as e:
        logging.error("Invalid token. Reason: %s", str(e))
    except Exception as ex:
        logging.error("An error occurred during token validation: %s", str(ex))

    return None

def isValid(token):
    try:
        token_object = jwt.decode(token, SECRET_KEY, algorithms=['HS256'], options={"require": ["aud", "iss"]})

        if not validateClaims(token_object):
            return False

        logging.info("Token is valid.")
        return True  
    except jwt.InvalidTokenError:
        logging.warning("Invalid token detected.")
        return False
    except Exception as ex:
        logging.error("Validation error: %s", str(ex))
        return False

def validateClaims(token_object):
    expected_audience = os.getenv("EXPECTED_AUDIENCE")
    expected_issuer = os.getenv("EXPECTED_ISSUER")

    if token_object.get('aud') != expected_audience:
        logging.warning("Unexpected audience in token.")
        return False

    if token_object.get('iss') != expected_issuer:
        logging.warning("Unexpected issuer in token.")
        return False

    if 'exp' in token_object and token_object['exp'] < datetime.utcnow().timestamp():
        logging.warning("Token is expired.")
        return False

    if 'iat' in token_object and token_object['iat'] > datetime.utcnow().timestamp():
        logging.warning("Token issued in the future.")
        return False

    return True

