from flask import Flask, request, jsonify
import lxml.etree
import bcrypt
import os

app = Flask(__name__)

# Dummy user database
users_db = {
    'admin': bcrypt.hashpw(b'secret', bcrypt.gensalt())
}

def checkPassword(userid, password):
    if userid in users_db:
        return bcrypt.checkpw(password.encode('utf-8'), users_db[userid])
    return False

@app.post("/upload")
def upload():
    xml_file = request.files.get('file')
    user_credentials = request.form.get('credentials')

    if xml_file and user_credentials:
        userid, password = user_credentials.split(':')

        if checkPassword(userid, password):
            parser = lxml.etree.XMLParser(resolve_entities=False)
            try:
                tree = lxml.etree.parse(xml_file.stream, parser)
                return jsonify({"message": "XML uploaded and credentials validated"}), 200
            except lxml.etree.XMLSyntaxError:
                return jsonify({"message": "Invalid XML format"}), 400
        else:
            return jsonify({"message": "Invalid credentials"}), 403

    return jsonify({"message": "File and credentials are required"}), 400

if __name__ == "__main__":
    app.run(debug=False, host='0.0.0.0', port=int(os.environ.get("PORT", 5000)))

