from flask import Flask, request, jsonify
import lxml.etree
import logging
from functools import wraps
import time

app = Flask(__name__)

# Set up logging
logging.basicConfig(level=logging.INFO)

MAX_XML_SIZE = 2 * 1024 * 1024  # 2 MB limit
MAX_XML_DEPTH = 10  # example: maximum depth for nested elements
RATE_LIMIT = 5  # Max requests per minute
request_counts = {}

def validate_xml_depth(element, current_depth):
    if current_depth > MAX_XML_DEPTH:
        raise ValueError("XML depth exceeds maximum limit")
    for child in element:
        validate_xml_depth(child, current_depth + 1)

def rate_limiter(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        client_ip = request.remote_addr
        current_time = time.time()
        if client_ip not in request_counts:
            request_counts[client_ip] = []
        request_counts[client_ip] = [timestamp for timestamp in request_counts[client_ip] if timestamp > current_time - 60]

        if len(request_counts[client_ip]) >= RATE_LIMIT:
            return jsonify({"error": "Too many requests"}), 429

        request_counts[client_ip].append(current_time)
        return func(*args, **kwargs)
    return wrapper

@app.post("/upload")
@rate_limiter
def upload():
    if request.content_type != 'application/xml':
        return jsonify({"error": "Unsupported Media Type"}), 415

    xml_src = request.data

    if len(xml_src) > MAX_XML_SIZE:
        return jsonify({"error": "Payload too large"}), 413

    try:
        parser = lxml.etree.XMLParser(resolve_entities=False, huge_tree=False, strip_cdata=False)
        tree = lxml.etree.fromstring(xml_src, parser)

        validate_xml_depth(tree, 1)

        # Further input validation logic can be applied here based on XSD

        response = lxml.etree.tostring(tree, pretty_print=True).decode()
        return response, 200
    except lxml.etree.XMLSyntaxError:
        logging.error("Invalid XML format")
        return jsonify({"error": "Invalid XML format"}), 400
    except ValueError as ve:
        logging.error(f"Depth validation error: {ve}")
        return jsonify({"error": "XML depth exceeds maximum limit"}), 400
    except Exception as e:
        logging.error(f"An error occurred: {e}")
        return jsonify({"error": "An error occurred while processing the XML"}), 500

@app.after_request
def apply_security_headers(response):
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Content-Security-Policy"] = "default-src 'self'; object-src 'none';"
    response.headers["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"
    response.headers["X-XSS-Protection"] = "1; mode=block"
    return response

