    ]
    pattern = r'^(\d{1,3}\.){3}\d{1,3}$'
    if re.match(pattern, ip) and all(0 <= int(part) <= 255 for part in ip.split('.')):
        if any(re.match(priv, ip) for priv in private_ips):
            logging.warning(f"Private IP detected: {ip}")
            return False
        return True
    logging.warning(f"Invalid IP detected: {ip}")
    return False

def parseUDPpacket(data):
    stripped_data = data[:15].strip()
    if len(stripped_data) == 0:
        logging.warning("Received empty packet")
        return None
    return stripped_data

