        logging.warning("Received empty packet")
        return None
    return stripped_data

def sendResponse(ip, response):
    if is_valid_ip(ip):
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
            sock.sendto(response.encode(), (ip, int(os.getenv('UDP_PORT', 12345))))

def rate_limit(limit, interval):
    timestamps = deque()
    lock = threading.Lock()

    def decorator(func):
        def wrapper():
            nonlocal timestamps
            with lock:
                current_time = time.time()
                while timestamps and current_time - timestamps[0] >= interval:
                    timestamps.popleft()
                if len(timestamps) < limit:
                    timestamps.append(current_time)
                    return func()
                logging.warning("Rate limit exceeded")
                return False
        return wrapper
    return decorator

@rate_limit(10, 1)  # Limit to 10 requests per second
def request_allowed():
    return True

def sendData():
    port = os.getenv('UDP_PORT', None)
    if port is None or not port.isdigit() or not (1 <= int(port) <= 65535):
        logging.error("Invalid or missing UDP port. Please set a valid port.")
        return

    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
        sock.bind(('0.0.0.0', int(port)))
        logging.info("Server is running...")
        while True:
            try:
                data, addr = sock.recvfrom(2048)  # Increased buffer size
                ip_address = addr[0]
                packet_data = parseUDPpacket(data)
                if packet_data and request_allowed():
                    sendResponse(ip_address, "Acknowledged")
                    logging.info(f"Processed packet from {ip_address}: {packet_data}")
            except socket.error as e:
                logging.error(f"Socket error: {e}")
            except Exception as e:
                logging.error(f"Error: {e}")

sendData()

